use std::io::{Read,Write};use spore_core::{cell_fresh_sweep_registration_v1::{Endpoint,Slot},cell_sweep_old_fresh_merge_v1::merge};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=5*204{return Err("expected five 204-byte cases".into())}let mut out=Vec::new();for row in input.chunks_exact(204){let word=|p:usize|u32::from_le_bytes(row[p..p+4].try_into().unwrap());let axis=word(0) as usize;let oldn=word(4) as usize;let newn=word(8) as usize;if oldn>8||newn>8{return Err("invalid counts".into())}let mut slots=Vec::new();for p in (12..76).step_by(16){slots.push(Slot{actor:word(p),tag:word(p+4),endpoint_links:std::array::from_fn(|i|u16::from_le_bytes(row[p+8+2*i..p+10+2*i].try_into().unwrap()))})}let get=|p:usize|Endpoint{opening:u16::from_le_bytes(row[p..p+2].try_into().unwrap()),slot:u16::from_le_bytes(row[p+2..p+4].try_into().unwrap()),value_bits:word(p+4)};let old:Vec<_>=(0..8).map(|i|get(76+8*i)).collect();let fresh:Vec<_>=(0..8).map(|i|get(140+8*i)).collect();let m=merge(axis,&slots,&old[..oldn],&fresh[..newn]).map_err(|e|format!("{e:?}"))?;for s in m.slots{out.extend(s.actor.to_le_bytes());out.extend(s.tag.to_le_bytes());for x in s.endpoint_links{out.extend(x.to_le_bytes())}}let count=m.endpoints.len();for e in m.endpoints.iter().chain(old[count..].iter()){out.extend(e.opening.to_le_bytes());out.extend(e.slot.to_le_bytes());out.extend(e.value_bits.to_le_bytes())}out.extend((count as u32).to_le_bytes());}std::io::stdout().write_all(&out)?;Ok(())}
